import logging

logger = logging.getLogger(__name__)


class Registry:
    def __init__(self) -> None:
        self.tools_dict = {}

    def add(self, tool) -> None:
        if tool.name in self.tools_dict:
            logger.warning("duplicate tool name %s", tool.name)
        self.tools_dict[tool.name] = tool
